+/**
+ * Variance per item between two days (inclusive): theoretical use from the
+ * sales sold in those days, actual use from every consume movement, and
+ * actual minus theoretical. Only items where either is above zero.
+ */
+export function varianceReport(store, from, to) {
+  const inRange = (instant) => {
+    const day = dayOf(instant);
+    return day >= from && day <= to;
+  };
+  const theory = new Map();
+  for (const s of store.data.sales ?? []) {
+    if (!inRange(s.soldAt)) continue;
+    const dish = (store.data.dishes ?? []).find((d) => d.id === s.dishId);
+    const recipe = dish && store.data.recipes.find((r) => r.id === dish.recipeId);
+    if (!recipe) continue;
+    for (const n of scaled(recipe, s.qty)) theory.set(n.itemId, (theory.get(n.itemId) ?? 0) + n.qty);
+  }
+  const batchItem = new Map(store.data.batches.map((b) => [b.id, b.itemId]));
+  const actual = new Map();
+  for (const m of store.data.movements) {
+    if (m.type !== "consume" || !inRange(m.at)) continue;
+    const itemId = batchItem.get(m.batchId);
+    if (itemId !== undefined) actual.set(itemId, (actual.get(itemId) ?? 0) + m.qty);
+  }
+  const r3 = (x) => Math.round(x * 1000) / 1000;
+  return listItems(store)
+    .map((i) => {
+      const t = r3(theory.get(i.id) ?? 0);
+      const a = r3(actual.get(i.id) ?? 0);
+      return { itemId: i.id, name: i.name, unit: i.unit, theoretical: t, actual: a, difference: r3(a - t) };
+    })
+    .filter((l) => l.theoretical > 0 || l.actual > 0)
+    .sort((x, y) => x.itemId - y.itemId);
+}
